import json,os,urllib.request
TOK=os.environ["TOK"]; NWO=os.environ["NWO"]; O,R=NWO.split("/")
FRAGS=[["allowUpdateBranch", "allowUpdateBranch"], ["archivedAt", "archivedAt"], ["assignableUsers", "assignableUsers(first:1){__typename}"], ["autoMergeAllowed", "autoMergeAllowed"], ["branchProtectionRules", "branchProtectionRules(first:1){__typename}"], ["codeOfConduct", "codeOfConduct{__typename}"], ["codeowners", "codeowners{__typename}"], ["collaborators", "collaborators(first:1){__typename}"], ["commitComments", "commitComments(first:1){__typename}"], ["contactLinks", "contactLinks{__typename}"], ["contributingGuidelines", "contributingGuidelines{__typename}"], ["createdAt", "createdAt"], ["databaseId", "databaseId"], ["defaultBranchRef", "defaultBranchRef{__typename}"], ["deleteBranchOnMerge", "deleteBranchOnMerge"], ["dependencyGraphManifests", "dependencyGraphManifests(first:1){__typename}"], ["deployKeys", "deployKeys(first:1){__typename}"], ["deployments", "deployments(first:1){__typename}"], ["description", "description"], ["descriptionHTML", "descriptionHTML"], ["discussion", "discussion(number:1){__typename}"], ["discussionCategories", "discussionCategories(first:1){__typename}"], ["discussionCategory", "discussionCategory(slug:\"x\"){__typename}"], ["discussions", "discussions(first:1){__typename}"], ["diskUsage", "diskUsage"], ["environment", "environment(name:\"main\"){__typename}"], ["environments", "environments(first:1){__typename}"], ["forkCount", "forkCount"], ["forkingAllowed", "forkingAllowed"], ["forks", "forks(first:1){__typename}"], ["fundingLinks", "fundingLinks{__typename}"], ["hasDiscussionsEnabled", "hasDiscussionsEnabled"], ["hasIssuesEnabled", "hasIssuesEnabled"], ["hasProjectsEnabled", "hasProjectsEnabled"], ["hasPullRequestsEnabled", "hasPullRequestsEnabled"], ["hasSponsorshipsEnabled", "hasSponsorshipsEnabled"], ["hasVulnerabilityAlertsEnabled", "hasVulnerabilityAlertsEnabled"], ["hasWikiEnabled", "hasWikiEnabled"], ["homepageUrl", "homepageUrl"], ["id", "id"], ["interactionAbility", "interactionAbility{__typename}"], ["isArchived", "isArchived"], ["isBlankIssuesEnabled", "isBlankIssuesEnabled"], ["isDisabled", "isDisabled"], ["isEmpty", "isEmpty"], ["isFork", "isFork"], ["isInOrganization", "isInOrganization"], ["isLocked", "isLocked"], ["isMirror", "isMirror"], ["isPrivate", "isPrivate"], ["isSecurityPolicyEnabled", "isSecurityPolicyEnabled"], ["isTemplate", "isTemplate"], ["isUserConfigurationRepository", "isUserConfigurationRepository"], ["issue", "issue(number:1){__typename}"], ["issueCreationPolicy", "issueCreationPolicy"], ["issueFields", "issueFields(first:1){__typename}"], ["issueOrPullRequest", "issueOrPullRequest(number:1){__typename}"], ["issueTemplates", "issueTemplates{__typename}"], ["issueType", "issueType(name:\"main\"){__typename}"], ["issueTypes", "issueTypes(first:1){__typename}"], ["issues", "issues(first:1){__typename}"], ["label", "label(name:\"main\"){__typename}"], ["labels", "labels(first:1){__typename}"], ["languages", "languages(first:1){__typename}"], ["latestRelease", "latestRelease{__typename}"], ["licenseInfo", "licenseInfo{__typename}"], ["lockReason", "lockReason"], ["mentionableUsers", "mentionableUsers(first:1){__typename}"], ["mergeCommitAllowed", "mergeCommitAllowed"], ["mergeCommitMessage", "mergeCommitMessage"], ["mergeCommitTitle", "mergeCommitTitle"], ["mergeQueue", "mergeQueue{__typename}"], ["milestone", "milestone(number:1){__typename}"], ["milestones", "milestones(first:1){__typename}"], ["mirrorUrl", "mirrorUrl"], ["name", "name"], ["nameWithOwner", "nameWithOwner"], ["object", "object{__typename}"], ["openGraphImageUrl", "openGraphImageUrl"], ["owner", "owner{__typename}"], ["packages", "packages(first:1){__typename}"], ["parent", "parent{__typename}"], ["pinnedDiscussions", "pinnedDiscussions(first:1){__typename}"], ["pinnedEnvironments", "pinnedEnvironments(first:1){__typename}"], ["pinnedIssues", "pinnedIssues(first:1){__typename}"], ["planFeatures", "planFeatures{__typename}"], ["primaryLanguage", "primaryLanguage{__typename}"], ["projectV2", "projectV2(number:1){__typename}"], ["projectsResourcePath", "projectsResourcePath"], ["projectsUrl", "projectsUrl"], ["projectsV2", "projectsV2(first:1){__typename}"], ["pullRequest", "pullRequest(number:1){__typename}"], ["pullRequestCreationCapConfig", "pullRequestCreationCapConfig{__typename}"], ["pullRequestCreationPolicy", "pullRequestCreationPolicy"], ["pullRequestTemplates", "pullRequestTemplates{__typename}"], ["pullRequests", "pullRequests(first:1){__typename}"], ["pushedAt", "pushedAt"], ["rebaseMergeAllowed", "rebaseMergeAllowed"], ["recentProjects", "recentProjects(first:1){__typename}"], ["ref", "ref(qualifiedName:\"refs/heads/main\"){__typename}"], ["refs", "refs(refPrefix:\"refs/heads/\",first:1){__typename}"], ["release", "release(tagName:\"v1\"){__typename}"], ["releases", "releases(first:1){__typename}"], ["repositoryCustomPropertyValues", "repositoryCustomPropertyValues(first:1){__typename}"], ["repositoryTopics", "repositoryTopics(first:1){__typename}"], ["resourcePath", "resourcePath"], ["rulesets", "rulesets(first:1){__typename}"], ["securityPolicyUrl", "securityPolicyUrl"], ["shortDescriptionHTML", "shortDescriptionHTML"], ["squashMergeAllowed", "squashMergeAllowed"], ["squashMergeCommitMessage", "squashMergeCommitMessage"], ["squashMergeCommitTitle", "squashMergeCommitTitle"], ["sshUrl", "sshUrl"], ["stargazerCount", "stargazerCount"], ["stargazers", "stargazers(first:1){__typename}"], ["submodules", "submodules(first:1){__typename}"], ["tempCloneToken", "tempCloneToken"], ["templateRepository", "templateRepository{__typename}"], ["updatedAt", "updatedAt"], ["url", "url"], ["usesCustomOpenGraphImage", "usesCustomOpenGraphImage"], ["viewerCanAdminister", "viewerCanAdminister"], ["viewerCanCreateIssues", "viewerCanCreateIssues"], ["viewerCanSeeIssueFields", "viewerCanSeeIssueFields"], ["viewerCanSubscribe", "viewerCanSubscribe"], ["viewerCanUpdateTopics", "viewerCanUpdateTopics"], ["viewerContentWarning", "viewerContentWarning{__typename}"], ["viewerDefaultCommitEmail", "viewerDefaultCommitEmail"], ["viewerDefaultMergeMethod", "viewerDefaultMergeMethod"], ["viewerHasStarred", "viewerHasStarred"], ["viewerPermission", "viewerPermission"], ["viewerPossibleCommitEmails", "viewerPossibleCommitEmails"], ["viewerSubscription", "viewerSubscription"], ["visibility", "visibility"], ["vulnerabilityAlert", "vulnerabilityAlert(number:1){__typename}"], ["vulnerabilityAlerts", "vulnerabilityAlerts(first:1){__typename}"], ["watchers", "watchers(first:1){__typename}"], ["webCommitSignoffRequired", "webCommitSignoffRequired"]]
def gq(sel):
    q=json.dumps({"query":'query{repository(owner:"%s",name:"%s"){%s}}'%(O,R,sel)}).encode()
    req=urllib.request.Request("https://api.github.com/graphql",data=q,headers={
        "Authorization":"Bearer "+TOK,"Content-Type":"application/json","User-Agent":"fieldsweep"})
    try:
        with urllib.request.urlopen(req) as r: d=json.loads(r.read())
    except Exception as e:
        try: d=json.loads(e.read())
        except Exception: return "HTTPERR"
    if d.get("errors"):
        e=d["errors"][0]; return "ERR|"+str(e.get("type"))+"|"+e.get("message","")[:70]
    return "OK|"+json.dumps(d.get("data",{}).get("repository"))[:300]
for n,f in FRAGS:
    print("F|%-34s|%s"%(n,gq(f)))
